package org.sleepwell.app;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Device-local requested engine/voice selection. Playback is only on the guide's explicit Play button. */
public final class NarrationVoiceActivity extends Activity implements NarrationVoiceDiscovery.Observer {
 private NarrationVoiceDiscovery query;private NarrationVoice draft=NarrationVoice.AUTO;private String engine="",error="";private int page;private Dialog dialog;private boolean resumed;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{draft=NarrationVoice.load(this);engine=draft.engine;}catch(RuntimeException invalid){error="The saved voice is unreadable. Choose Auto or refresh an installed engine, then Save.";}if(saved!=null)try{draft=new NarrationVoice(saved.getString("engine",""),saved.getString("name",""),saved.getString("locale",""));engine=saved.getString("requested",draft.engine);page=saved.getInt("page");}catch(RuntimeException invalid){draft=NarrationVoice.AUTO;}query=new NarrationVoiceDiscovery(getApplicationContext());query.observe(this);}
 public void changed(){if(isDestroyed())return;if(engine.isEmpty()&&!query.installed.isEmpty())engine=query.installed.get(0).name;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Offline narration voice",this::finish);Design.space(body,14);Design.text(body,"English guide · installed voices only",18,600,Design.INK);Design.space(body,8);Design.text(body,"Select a requested speech engine and an engine-declared installed offline English voice. The original guide is English; this does not translate it. No speech or download starts on this screen.",13,400,Design.MUTED);Design.space(body,12);row(body,"Auto · offline English",draft.automatic(),()->{draft=NarrationVoice.AUTO;error="";changed();});Design.item(body,"settings","Requested engine",engine.isEmpty()?"None installed":engine,this::engines);Design.button(body,query.busy?"Checking voices…":"Refresh installed voices",false,()->{if(hasWindowFocus()){error="";page=0;if(engine.isEmpty())query.inventory();else query.refresh(engine);}}).setEnabled(!query.busy);Design.text(body,query.message,13,500,Design.MUTED);if(!draft.automatic())Design.text(body,"Draft: "+draft.name+" · "+draft.locale+"\nRequested engine: "+draft.engine,12,500,Design.BROWN);Design.space(body,8);
  int pages=Math.max(1,(query.voices.size()+19)/20);page=Math.max(0,Math.min(page,pages-1));for(int n=page*20;n<Math.min(query.voices.size(),(page+1)*20);n++){NarrationVoice voice=query.voices.get(n);row(body,voice.name+" · "+voice.locale,!draft.automatic()&&draft.engine.equals(voice.engine)&&draft.name.equals(voice.name)&&draft.locale.equals(voice.locale),()->{draft=voice;error="";changed();});}if(pages>1){Design.text(body,"Voice page "+(page+1)+" / "+pages,12,400,Design.MUTED);if(page>0)Design.button(body,"Previous voices",false,()->{page--;changed();});if(page+1<pages)Design.button(body,"More voices",false,()->{page++;changed();});}Design.space(body,12);Design.text(body,"Android may fall back from a requested engine; the public API does not prove the active engine package. Play accepts only the exact selected voice name and locale when it is still declared offline, installed and English-supported. If missing, narration stops with an error; it never silently selects a different voice. Offline status is the engine's declaration.",12,400,Design.MUTED);Design.text(body,"This device-local identity is excluded from portable settings profiles. Cancel keeps the saved selection. Save is silent; preview from Play narration in the guide.",12,400,Design.MUTED);if(!error.isEmpty())Design.text(body,error,13,500,Design.BROWN);LinearLayout footer=RecordUi.footer(body);Design.button(footer,"Save voice selection",true,this::save).setEnabled(!query.busy&&query.verified(draft));Design.button(footer,"Cancel",false,this::finish);
 }
 private void row(LinearLayout body,String title,boolean selected,Runnable click){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,58));Design.pad(row,10,10);row.setBackground(Design.touch(this,selected?Design.SOFT:android.graphics.Color.TRANSPARENT,12));row.addView(new Design.Icon(this,selected?"check":"sound",Design.BROWN),new LinearLayout.LayoutParams(Design.dp(this,24),Design.dp(this,24)));TextView label=Design.text(this,title,14,500,Design.INK);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=Design.dp(this,12);row.addView(label,lp);row.setSelected(selected);row.setFocusable(true);row.setContentDescription(title+(selected?" selected":""));row.setOnClickListener(v->{if(!query.busy)click.run();});body.addView(row);}
 private void engines(){if(query.busy)return;if(query.installed.isEmpty()){query.inventory();return;}String[] labels=new String[query.installed.size()];int selected=-1;for(int i=0;i<labels.length;i++){NarrationVoiceEngine.Installed item=query.installed.get(i);labels[i]=item.label+" · "+item.name;if(item.name.equals(engine))selected=i;}dialog=SleepPicker.choices(this,"Requested speech engine",labels,selected,index->{engine=query.installed.get(index).name;query.cancel();page=0;changed();});}
 private void save(){if(!resumed||!hasWindowFocus()||!query.verified(draft))return;try{draft.save(this);setResult(RESULT_OK);finish();}catch(RuntimeException failure){error=failure.getMessage()==null?"Voice selection could not be saved.":failure.getMessage();changed();}}
 @Override protected void onResume(){super.onResume();resumed=true;}
 @Override protected void onPause(){resumed=false;query.cancel();super.onPause();}
 @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("engine",draft.engine);out.putString("name",draft.name);out.putString("locale",draft.locale);out.putString("requested",engine);out.putInt("page",page);}
 @Override protected void onDestroy(){if(dialog!=null)dialog.dismiss();query.detach(this);query.close();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
